param(
  [string]$ArchiveName = (Join-Path $PSScriptRoot '..\annual-reports'),
  [string]$OutputName = (Join-Path $PSScriptRoot '..\output\regulatory-language-analysis.html'),
  [string]$ShardDirectory = (Join-Path $PSScriptRoot '..\data\intermediate'),
  [string]$PanelName = 'ASX200'
)

$ErrorActionPreference = 'Stop'
$projectRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path

$archive = (Resolve-Path $ArchiveName).Path
$outPath = if ([IO.Path]::IsPathRooted($OutputName)) { $OutputName } else { Join-Path (Get-Location) $OutputName }
$archiveDisplay = Split-Path -Path $archive -Leaf
$years = 2015..2025

# The ASX200 report can link to the separately rendered ASX50-only view.
$asx50TickerSet=@{}
$asx50Manifest=Join-Path $projectRoot 'data\manifests\asx50-companies.json'
if(Test-Path -LiteralPath $asx50Manifest){
  $asx50Rows=Get-Content -LiteralPath $asx50Manifest -Raw|ConvertFrom-Json
  foreach($row in $asx50Rows){$asx50TickerSet[[string]$row.Ticker]=$true}
}

# Broad GICS-style sectors are loaded from the local ASX listing snapshot. Four
# historical/renamed tickers are assigned transparent fallbacks below.
$sectorByCode = @{}
$subsectorByCode = @{}
$sectorSnapshot = Join-Path $projectRoot 'data\manifests\asx-listed-companies.csv'
if (Test-Path -LiteralPath $sectorSnapshot) {
  $sectorRows = @(Get-Content -LiteralPath $sectorSnapshot | Select-Object -Skip 2 | ConvertFrom-Csv -Header Company,Code,IndustryGroup)
  foreach ($row in $sectorRows) { if ($row.Code -and $row.IndustryGroup) { $sectorByCode[[string]$row.Code] = [string]$row.IndustryGroup; $subsectorByCode[[string]$row.Code] = [string]$row.IndustryGroup } }
}
$sectorAliases = @{ TPM = 'TPG' }
$sectorFallbacks = @{
  GUD = 'Consumer Discretionary'
  QUB = 'Industrials'
  SCP = 'Real Estate'
  TPM = 'Communication Services'
  SGH = 'Industrials'
  VAS = 'Financials'
}
function Get-Sector([string]$ticker) {
  if ($sectorFallbacks.ContainsKey($ticker)) { return $sectorFallbacks[$ticker] }
  $lookup = if ($sectorAliases.ContainsKey($ticker)) { $sectorAliases[$ticker] } else { $ticker }
  $industry = if ($sectorByCode.ContainsKey($lookup)) { $sectorByCode[$lookup] } else { '' }
  switch -Regex ($industry) {
    '^(Banks|Financial Services|Insurance)$' { return 'Financials' }
    '^(Equity Real Estate Investment Trusts \(REITs\)|Real Estate Management & Development)$' { return 'Real Estate' }
    '^Materials$' { return 'Materials' }
    '^Energy$' { return 'Energy' }
    '^Utilities$' { return 'Utilities' }
    '^(Transportation|Commercial & Professional Services|Capital Goods)$' { return 'Industrials' }
    '^(Consumer Services|Consumer Durables & Apparel|Consumer Discretionary Distribution & Retail)$' { return 'Consumer Discretionary' }
    '^(Consumer Staples Distribution & Retail|Food, Beverage & Tobacco)$' { return 'Consumer Staples' }
    '^(Health Care Equipment & Services|Pharmaceuticals, Biotechnology & Life Sciences)$' { return 'Health Care' }
    '^(Media & Entertainment|Telecommunication Services)$' { return 'Communication Services' }
    '^Software & Services$' { return 'Information Technology' }
    default { return 'Other / unclassified' }
  }
}
function Get-Subsector([string]$ticker) {
  $lookup = if ($sectorAliases.ContainsKey($ticker)) { $sectorAliases[$ticker] } else { $ticker }
  if ($subsectorByCode.ContainsKey($lookup)) { return $subsectorByCode[$lookup] }
  if ($sectorFallbacks.ContainsKey($ticker)) { return $sectorFallbacks[$ticker] }
  return 'Other / unclassified'
}
$hqByCode = @{
  AGL='NSW'; AIA='New Zealand'; ALD='NSW'; ALL='NSW'; ALQ='QLD'; AMC='Switzerland'; AMP='NSW'; ANN='VIC'; ANZ='VIC'; APA='NSW'; ASX='NSW'; AZJ='QLD'; BEN='VIC'; BGA='NSW'; BHP='VIC'; BOQ='QLD'; BPT='NSW'; BRG='VIC'; BSL='VIC'; BWP='WA'; BXB='NSW'; CAR='VIC'; CBA='NSW'; CGF='NSW'; CHC='NSW'; CNU='New Zealand'; COH='NSW'; CPU='VIC'; CQR='NSW'; CSL='VIC'; DOW='NSW'; DXS='NSW'; EVN='NSW'; FBU='New Zealand'; FLT='QLD'; FMG='WA'; FPH='New Zealand'; GMG='QLD'; GPT='NSW'; GUD='VIC'; HVN='VIC'; IAG='NSW'; IGO='WA'; ILU='WA'; IPL='VIC'; JBH='VIC'; JHX='Ireland'; LLC='NSW'; LYC='WA'; MGR='NSW'; MIN='WA'; MPL='VIC'; MQG='NSW'; NAB='VIC'; NEC='NSW'; NEM='US'; NST='WA'; NWS='US'; ORA='VIC'; ORG='NSW'; ORI='VIC'; PME='VIC'; PMV='VIC'; PTM='NSW'; QAN='NSW'; QBE='NSW'; QUB='NSW'; REA='VIC'; RHC='NSW'; RIO='UK'; RMD='US'; RRL='WA'; S32='WA'; SCG='NSW'; SCP='NSW'; SDF='NSW'; SEK='VIC'; SGM='US'; SGH='NSW'; SGP='NSW'; SHL='NSW'; SIG='VIC'; SKC='New Zealand'; SOL='NSW'; SPK='New Zealand'; STO='SA'; SUL='QLD'; SUN='QLD'; SVW='NSW'; TAH='VIC'; TCL='VIC'; TLS='VIC'; TNE='QLD'; TPM='NSW'; TWE='VIC'; VAS='VIC'; WBC='NSW'; WDS='WA'; WES='WA'; WOR='NSW'; WOW='NSW'; XRO='New Zealand'
}
function Get-HQRegion([string]$ticker) { if ($hqByCode.ContainsKey($ticker)) { return $hqByCode[$ticker] }; return 'Other / not assigned' }
$exposureByCode = @{
  AGL='Home-market focused (Australia/NZ)'; AIA='Home-market focused (Australia/NZ)'; ALD='Multinational / material international exposure'; ALL='Multinational / material international exposure'; ALQ='Multinational / material international exposure'; AMC='Multinational / material international exposure'; AMP='Home-market focused (Australia/NZ)'; ANN='Multinational / material international exposure'; ANZ='Multinational / material international exposure'; APA='Home-market focused (Australia/NZ)'; ASX='Home-market focused (Australia/NZ)'; AZJ='Home-market focused (Australia/NZ)'; BEN='Home-market focused (Australia/NZ)'; BGA='Home-market focused (Australia/NZ)'; BHP='Multinational / material international exposure'; BOQ='Home-market focused (Australia/NZ)'; BPT='Home-market focused (Australia/NZ)'; BRG='Multinational / material international exposure'; BSL='Multinational / material international exposure'; BWP='Home-market focused (Australia/NZ)'; BXB='Multinational / material international exposure'; CAR='Multinational / material international exposure'; CBA='Multinational / material international exposure'; CGF='Home-market focused (Australia/NZ)'; CHC='Multinational / material international exposure'; CNU='Home-market focused (Australia/NZ)'; COH='Multinational / material international exposure'; CPU='Multinational / material international exposure'; CQR='Home-market focused (Australia/NZ)'; CSL='Multinational / material international exposure'; DOW='Home-market focused (Australia/NZ)'; DXS='Home-market focused (Australia/NZ)'; EVN='Multinational / material international exposure'; FBU='Multinational / material international exposure'; FLT='Multinational / material international exposure'; FMG='Home-market focused (Australia/NZ)'; FPH='Multinational / material international exposure'; GMG='Multinational / material international exposure'; GPT='Home-market focused (Australia/NZ)'; GUD='Home-market focused (Australia/NZ)'; HVN='Multinational / material international exposure'; IAG='Home-market focused (Australia/NZ)'; IGO='Home-market focused (Australia/NZ)'; ILU='Home-market focused (Australia/NZ)'; IPL='Multinational / material international exposure'; JBH='Home-market focused (Australia/NZ)'; JHX='Multinational / material international exposure'; LLC='Multinational / material international exposure'; LYC='Multinational / material international exposure'; MGR='Home-market focused (Australia/NZ)'; MIN='Home-market focused (Australia/NZ)'; MPL='Home-market focused (Australia/NZ)'; MQG='Multinational / material international exposure'; MTS='Home-market focused (Australia/NZ)'; NAB='Multinational / material international exposure'; NEC='Home-market focused (Australia/NZ)'; NEM='Multinational / material international exposure'; NST='Multinational / material international exposure'; NWS='Multinational / material international exposure'; ORA='Multinational / material international exposure'; ORG='Home-market focused (Australia/NZ)'; ORI='Multinational / material international exposure'; PME='Multinational / material international exposure'; PMV='Home-market focused (Australia/NZ)'; PTM='Multinational / material international exposure'; QAN='Multinational / material international exposure'; QBE='Multinational / material international exposure'; QUB='Home-market focused (Australia/NZ)'; REA='Multinational / material international exposure'; RHC='Multinational / material international exposure'; RIO='Multinational / material international exposure'; RMD='Multinational / material international exposure'; RRL='Home-market focused (Australia/NZ)'; S32='Multinational / material international exposure'; SCG='Home-market focused (Australia/NZ)'; SCP='Home-market focused (Australia/NZ)'; SDF='Home-market focused (Australia/NZ)'; SEK='Multinational / material international exposure'; SGM='Multinational / material international exposure'; SGH='Home-market focused (Australia/NZ)'; SGP='Home-market focused (Australia/NZ)'; SHL='Multinational / material international exposure'; SIG='Home-market focused (Australia/NZ)'; SKC='Home-market focused (Australia/NZ)'; SOL='Home-market focused (Australia/NZ)'; SPK='Home-market focused (Australia/NZ)'; STO='Multinational / material international exposure'; SUL='Home-market focused (Australia/NZ)'; SUN='Home-market focused (Australia/NZ)'; SVW='Home-market focused (Australia/NZ)'; TAH='Home-market focused (Australia/NZ)'; TCL='Multinational / material international exposure'; TLS='Home-market focused (Australia/NZ)'; TNE='Multinational / material international exposure'; TPM='Home-market focused (Australia/NZ)'; TWE='Multinational / material international exposure'; VAS='Home-market focused (Australia/NZ)'; WBC='Multinational / material international exposure'; WDS='Multinational / material international exposure'; WES='Home-market focused (Australia/NZ)'; WOR='Multinational / material international exposure'; WOW='Home-market focused (Australia/NZ)'; XRO='Multinational / material international exposure'
}
function Get-Exposure([string]$ticker) { if ($exposureByCode.ContainsKey($ticker)) { return $exposureByCode[$ticker] }; return 'Other / not assigned' }

$terms = [ordered]@{
  regulation = '(?i)\bregulat(?:ion|ions|ory)\b'
  compliance = '(?i)\bcomplian(?:ce|ces|t)\b'
  burden = '(?i)\bburdens?\b'
  requirement = '(?i)\brequirements?\b'
  regulator = '(?i)\bregulators?\b'
  legislation = '(?i)\blegislat(?:ion|ions|ive|ed)\b'
}
$themePatterns = [ordered]@{
  'Compliance and governance' = '(?i)\b(compliance|governance|ethic|conduct|control framework|internal control|code of conduct|anti[- ]bribery|whistleblow)\w*\b'
  'Regulatory change and uncertainty' = '(?i)\b(regulatory change|regulatory reform|new legislation|proposed legislation|evolving regulation|changing regulation|regulatory environment|policy change|law reform)\b'
  'Reporting, disclosure and assurance' = '(?i)\b(reporting|disclos\w*|audit\w*|assurance|statutory financial|financial statements|annual report|external auditor)\w*\b'
  'Direct cost and resourcing' = '(?i)\b(cost|costs|expense|expenses|fee|fees|resource|resourcing|staffing|burden|investment required|financial impact)\w*\b'
  'Systems, data and process implementation' = '(?i)\b(system\w*|data|process\w*|implement\w*|monitor\w*|technology|platform|workflow|record[- ]keeping)\b'
  'Licensing, approvals and market access' = '(?i)\b(licen[cs]\w*|permit\w*|approval\w*|authori[sz]\w*|accredit\w*|concession\w*|market access)\b'
  'Environmental and climate obligations' = '(?i)\b(environment\w*|climate|emission\w*|carbon|biodiversity|pollution|rehabilitation|sustainab\w*)\b'
  'Financial, tax and prudential rules' = '(?i)\b(tax\w*|prudential|capital adequacy|solvency|liquidity|financial crime|anti[- ]money laundering|aml|ctf|sanction\w*)\b'
  'Safety, quality and workforce obligations' = '(?i)\b(health and safety|workplace|workforce|employee|employment|labour|labor|quality|product safety|occupational|modern slavery)\w*\b'
  'Privacy, cyber and data protection' = '(?i)\b(privacy|cyber\w*|data protection|personal information|data breach|information security|cybersecurity)\w*\b'
}
$frames = @('Cost or challenge','Obligation or control','Transition or anticipation','Opportunity or legitimacy','Descriptive or neutral')

function New-Aggregate {
  $h = [ordered]@{ Reports = 0; Words = 0; Coded = 0; Terms = [ordered]@{}; Themes = [ordered]@{}; Frames = [ordered]@{} }
  foreach ($k in $terms.Keys) { $h.Terms[$k] = 0 }
  foreach ($k in $themePatterns.Keys) { $h.Themes[$k] = 0 }
  foreach ($k in $frames) { $h.Frames[$k] = 0 }
  return ,$h
}
function H([string]$s) { if ($null -eq $s) { return '' }; return [System.Net.WebUtility]::HtmlEncode($s) }
Remove-Item Alias:h -Force -ErrorAction SilentlyContinue
function Num([double]$n) { return $n.ToString('N0',[Globalization.CultureInfo]::InvariantCulture) }
function Clean([string]$s) { if ($null -eq $s) { return '' }; $s=$s.Replace([string]::Concat([char]226,[char]8364,[char]8482),"'");$s=$s.Replace([string]::Concat([char]226,[char]8364,[char]8211),'-');$s=$s.Replace([string]::Concat([char]226,[char]8364,[char]8212),'-');$s=$s.Replace([string]::Concat([char]226,[char]8364,[char]157),'"');$s=$s.Replace([string]::Concat([char]226,[char]8364,[char]339),'"');$s=$s.Replace([string]::Concat([char]226,[char]8364,[char]166),'...');$s=$s.Replace([string]::Concat([char]194,[char]160),' ');return $s }
function Clean([string]$s) {
  if ($null -eq $s) { return '' }
  $s=$s.Replace([string]::Concat([char]226,[char]8364,[char]8482),"'")
  $s=$s.Replace([string]::Concat([char]226,[char]8364,[char]150),'-').Replace([string]::Concat([char]226,[char]8364,[char]151),'-')
  $s=$s.Replace([string]::Concat([char]226,[char]8364,[char]157),[string][char]34).Replace([string]::Concat([char]226,[char]8364,[char]147),[string][char]34).Replace([string]::Concat([char]226,[char]8364,[char]148),[string][char]34)
  $s=$s.Replace([string]::Concat([char]226,[char]8364,[char]339),'"').Replace([string]::Concat([char]226,[char]8364,[char]166),'...')
  $s=$s.Replace([string]::Concat([char]194,[char]160),' ')
  return $s
}
function One([double]$n) { return $n.ToString('0.0',[Globalization.CultureInfo]::InvariantCulture) }
function Rel([string]$company,[int]$year) {
  $p = @($archiveDisplay,$company,("$year - Annual Report.pdf"))
  return (($p | ForEach-Object { [Uri]::EscapeDataString($_).Replace("'",'%27') }) -join '/')
}

$complete = @()
foreach ($dir in (Get-ChildItem -LiteralPath $archive -Directory | Sort-Object Name)) {
  $ok = $true
  foreach ($y in $years) { if (!(Test-Path -LiteralPath (Join-Path $dir.FullName ("$y - Annual Report.pdf"))) ) { $ok = $false; break } }
  if ($ok -and $dir.Name -match '^(?<ticker>[^ ]+) - (?<company>.+)$') {
    $ticker = $Matches.ticker
    $complete += [pscustomobject]@{ Ticker = $ticker; Name = $Matches.company; Dir = $dir; Sector = (Get-Sector $ticker); Subsector = (Get-Subsector $ticker); IsASX50 = $asx50TickerSet.ContainsKey($ticker); HQRegion = (Get-HQRegion $ticker); Exposure = (Get-Exposure $ticker) }
  }
}
if ($complete.Count -eq 0) { throw 'No companies currently have a complete 2015-2025 run.' }

$yearAgg = @{}; $companyAgg = @{}; $sectorAgg = @{}; $sectorYearAgg = @{}; $hqAgg = @{}; $hqYearAgg = @{}; $exposureAgg = @{}; $exposureYearAgg = @{}; $records = New-Object System.Collections.ArrayList
foreach ($y in $years) { $yearAgg[$y] = New-Aggregate }
foreach ($c in $complete) {
  $companyAgg[$c.Ticker] = New-Aggregate
  if (!$sectorAgg.ContainsKey($c.Sector)) { $sectorAgg[$c.Sector] = New-Aggregate; $sectorYearAgg[$c.Sector] = @{}; foreach ($y in $years) { $sectorYearAgg[$c.Sector][$y] = New-Aggregate } }
  if (!$hqAgg.ContainsKey($c.HQRegion)) { $hqAgg[$c.HQRegion] = New-Aggregate; $hqYearAgg[$c.HQRegion] = @{}; foreach ($y in $years) { $hqYearAgg[$c.HQRegion][$y] = New-Aggregate } }
  if (!$exposureAgg.ContainsKey($c.Exposure)) { $exposureAgg[$c.Exposure] = New-Aggregate; $exposureYearAgg[$c.Exposure] = @{}; foreach ($y in $years) { $exposureYearAgg[$c.Exposure][$y] = New-Aggregate } }
}
foreach ($i in 0..7) {
  $f = Join-Path (Resolve-Path $ShardDirectory) ("balanced-regulatory-shard-$i.json")
  if (!(Test-Path -LiteralPath $f)) { throw "Missing completed shard $i" }
  $part = Get-Content -LiteralPath $f -Raw | ConvertFrom-Json
  foreach ($r in @($part)) {
    $termCounts = [ordered]@{}; $themeCounts = [ordered]@{}; $frameCounts = [ordered]@{}
    foreach ($k in $terms.Keys) { $termCounts[$k] = [int64]$r.Terms.PSObject.Properties[$k].Value }
    foreach ($k in $themePatterns.Keys) { $themeCounts[$k] = [int64]$r.Themes.PSObject.Properties[$k].Value }
    foreach ($k in $frames) { $frameCounts[$k] = [int64]$r.Frames.PSObject.Properties[$k].Value }
    $company = ($complete | Where-Object {$_.Ticker -eq [string]$r.Ticker} | Select-Object -First 1)
    if ($null -eq $company) { continue }
    [void]$records.Add([pscustomobject]@{Ticker=[string]$r.Ticker;Company=[string]$r.Company;Year=[int]$r.Year;Words=[int64]$r.Words;Coded=[int64]$r.Coded;Terms=$termCounts;Themes=$themeCounts;Frames=$frameCounts;Sector=$company.Sector;HQRegion=$company.HQRegion;Exposure=$company.Exposure;Evidence=(Clean ([string]$r.Evidence));Href=(Rel $company.Dir.Name ([int]$r.Year))})
    $ya = $yearAgg[[int]$r.Year]; $ca = $companyAgg[[string]$r.Ticker]; $sa = $sectorAgg[$company.Sector]; $sya = $sectorYearAgg[$company.Sector][[int]$r.Year]; $ha = $hqAgg[$company.HQRegion]; $hya = $hqYearAgg[$company.HQRegion][[int]$r.Year]; $ea = $exposureAgg[$company.Exposure]; $eya = $exposureYearAgg[$company.Exposure][[int]$r.Year]
    foreach ($a in @($ya,$ca,$sa,$sya,$ha,$hya,$ea,$eya)) {
      $a.Reports++; $a.Words += [int64]$r.Words; $a.Coded += [int64]$r.Coded
      foreach ($k in $terms.Keys) { $a.Terms[$k] += $termCounts[$k] }
      foreach ($k in $themePatterns.Keys) { $a.Themes[$k] += $themeCounts[$k] }
      foreach ($k in $frames) { $a.Frames[$k] += $frameCounts[$k] }
    }
  }
}
if ($records.Count -ne ($complete.Count * $years.Count)) { throw "Shard record count $($records.Count) does not match expected $($complete.Count * $years.Count)" }
if ($false) {
$tmpDir = Join-Path $env:TEMP ("balanced-regulatory-text-" + [guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tmpDir -Force | Out-Null
$reportIndex = 0
try {
  foreach ($c in $complete) {
    foreach ($y in $years) {
      $reportIndex++
      $pdf = Join-Path $c.Dir.FullName ("$y - Annual Report.pdf")
      $txt = Join-Path $tmpDir ("$($c.Ticker)-$y.txt")
      & $pdftotext -layout -enc UTF-8 $pdf $txt 2>$null
      $text = if (Test-Path -LiteralPath $txt) { Get-Content -LiteralPath $txt -Raw -Encoding UTF8 } else { '' }
      if ($null -eq $text) { $text = '' }
      $words = [regex]::Matches($text,'(?i)\b[A-Za-z][A-Za-z0-9''\-]*\b').Count
      $coded = 0; $themeCounts = [ordered]@{}; $frameCounts = [ordered]@{}; $termCounts = [ordered]@{}
      foreach ($k in $themePatterns.Keys) { $themeCounts[$k] = 0 }
      foreach ($k in $frames) { $frameCounts[$k] = 0 }
      foreach ($k in $terms.Keys) { $termCounts[$k] = [regex]::Matches($text,$terms[$k]).Count }
      $evidence = New-Object System.Collections.ArrayList
      $passages = [regex]::Split($text,'(?<=[\.!\?;:])\s+|\r?\n{2,}')
      foreach ($p0 in $passages) {
        $p = ($p0 -replace '\s+',' ').Trim()
        if ($p.Length -lt 35) { continue }
        $direct = $p -match '(?i)\b(regulat\w*|complian\w*|legislat\w*|statut\w*|licen[cs]\w*|permit\w*|approval\w*|obligat\w*|mandat\w*|regulator\w*|prudential|privacy|cyber\w*)\b'
        $support = ($p -match '(?i)\b(report\w*|audit\w*|assur\w*|disclos\w*|control\w*|monitor\w*|polic\w*|system\w*|process\w*|standard\w*)\b') -and ($p -match '(?i)\b(cost\w*|expense\w*|resource\w*|burden\w*|require\w*|obligat\w*|rule\w*|law\w*|act\b|compliance)\b')
        if (!($direct -or $support)) { continue }
        $coded++
        $matchedThemes = @()
        foreach ($k in $themePatterns.Keys) { if ($p -match $themePatterns[$k]) { $themeCounts[$k]++; $matchedThemes += $k } }
        $frame = 'Descriptive or neutral'
        if ($p -match '(?i)\b(cost|costs|expense|expenses|fee|fees|burden|challenge|difficult|complex|resource pressure|delay|risk)\w*\b') { $frame = 'Cost or challenge' }
        elseif ($p -match '(?i)\b(proposed|future|upcoming|evolving|changing|transition|reform|new regulation|prepare|prepar\w*|expected)\w*\b') { $frame = 'Transition or anticipation' }
        elseif ($p -match '(?i)\b(opportunit\w*|trust|trusted|legitimacy|leadership|value creation|competitive advantage)\b') { $frame = 'Opportunity or legitimacy' }
        elseif ($p -match '(?i)\b(required|requirement|obligation|comply|compliance|control|monitor|policy|procedure|assurance|audit)\w*\b') { $frame = 'Obligation or control' }
        $frameCounts[$frame]++
        if ($evidence.Count -lt 1) { [void]$evidence.Add($p.Substring(0,[Math]::Min(360,$p.Length))) }
      }
      $ya = $yearAgg[$y]; $ca = $companyAgg[$c.Ticker]
      foreach ($a in @($ya,$ca)) {
        $a.Reports++; $a.Words += $words; $a.Coded += $coded
        foreach ($k in $terms.Keys) { $a.Terms[$k] += $termCounts[$k] }
        foreach ($k in $themePatterns.Keys) { $a.Themes[$k] += $themeCounts[$k] }
        foreach ($k in $frames) { $a.Frames[$k] += $frameCounts[$k] }
      }
      [void]$records.Add([pscustomobject]@{Ticker=$c.Ticker;Company=$c.Name;Year=$y;Words=$words;Coded=$coded;Terms=$termCounts;Themes=$themeCounts;Frames=$frameCounts;Evidence=if($evidence.Count){$evidence[0]}else{''};Href=(Rel $c.Dir.Name $y)})
      if (($reportIndex % 25) -eq 0) { Write-Output "extracted=$reportIndex/$($complete.Count*11)" }
    }
  }
}
finally { if (Test-Path -LiteralPath $tmpDir) { Remove-Item -LiteralPath $tmpDir -Recurse -Force -ErrorAction SilentlyContinue } }
}

$total = New-Aggregate
foreach ($y in $years) {
  $a = $yearAgg[$y]; $total.Reports += $a.Reports; $total.Words += $a.Words; $total.Coded += $a.Coded
  foreach ($k in $terms.Keys) { $total.Terms[$k] += $a.Terms[$k] }
  foreach ($k in $themePatterns.Keys) { $total.Themes[$k] += $a.Themes[$k] }
  foreach ($k in $frames) { $total.Frames[$k] += $a.Frames[$k] }
}
$rate = @{}; foreach ($y in $years) { $a=$yearAgg[$y]; $six=0; foreach($k in $terms.Keys){$six += $a.Terms[$k]}; $rate[$y] = if($a.Words){100000*$six/$a.Words}else{0} }
$minRate = ($rate.Values | Measure-Object -Minimum).Minimum; $maxRate = ($rate.Values | Measure-Object -Maximum).Maximum
$yMin = [Math]::Floor(([double]$minRate - 20)/20)*20; $yMax = [Math]::Ceiling(([double]$maxRate + 20)/20)*20
if ($yMin -lt 0) {$yMin=0}; if ($yMax -le $yMin) {$yMax=$yMin+100}
$x0=100; $x1=930; $y0=35; $y1=275; $pts=@(); foreach($i in 0..($years.Count-1)){ $x=$x0+($x1-$x0)*$i/($years.Count-1); $yy=$y1-(($rate[$years[$i]]-$yMin)/($yMax-$yMin))*($y1-$y0); $pts += "$(One $x),$(One $yy)" }
$grid = New-Object System.Text.StringBuilder
