$viewSwitchHtml=if($PanelName -eq 'ASX200'){"<div class='view-switch panel'><span class='view-switch-label'>View</span><strong id='panel-scope-label'>ASX200</strong><button type='button' class='panel-toggle' id='panel-scope-toggle'>Show ASX50 only</button></div>"}else{"<div class='view-switch panel'><span class='view-switch-label'>View</span><strong>ASX50</strong><button type='button' class='panel-toggle' onclick=`"window.location.href='regulatory-burden-balanced-2015-2025.html'`">Switch to ASX200</button></div>"}
