d:first-child{white-space:nowrap}.evidence a{color:#1769aa;text-decoration:none}.evidence a:hover{text-decoration:underline}.note{color:#5b6770;font-style:italic}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}@media(max-width:850px){main{padding:18px}header{padding:26px 24px}h1{font-size:28px}.two{grid-template-columns:1fr}}code{background:#eef2f4;padding:1px 4px;border-radius:4px}footer{color:#5b6770;font-size:12px;margin-top:35px;border-top:1px solid #dce3e8;padding-top:13px}
